<script setup>
import {computed} from 'vue';import {useTimeline} from './useTimeline';import {sources,binsFor,clock} from './data';import TimeAxis from './TimeAxis.vue';
const {state,filtered,inspect,select}=useTimeline();
const entities=['T-041','T-208','T-312','T-509','ARCHIVE','SENSOR-A','OP-01','ALERT-SERVICE'];
const rows=computed(()=>entities.map(id=>{const events=filtered.value.filter(e=>e.target===id&&e.t<state.end&&(e.end??e.t)>=state.start);return {id,events,bins:binsFor(events,state.start,state.end,30)}}).filter(r=>r.events.length));
const pos=t=>Math.max(0,Math.min(100,(t-state.start)/(state.end-state.start)*100));
</script><template><div class="entity-board"><div class="lane-axis"><TimeAxis :start="state.start" :end="state.end"/><span>ישות משותפת</span></div><div class="entity-row" v-for="row in rows" :key="row.id"><div class="entity-track" dir="ltr"><template v-if="state.end-state.start>360"><button v-for="(b,i) in row.bins" :key="i" class="entity-stack" :class="{alert:b.alert}" :style="{left:i/30*100+'%',width:100/30+'%'}" :title="clock(b.start)+' · '+b.count+' רשומות'" @click="inspect(b.start,b.end,{target:row.id})"><i v-for="s in sources" :key="s.id" :style="{background:s.color,height:(b.bySource[s.id]/Math.max(1,b.count)*34)+'px'}"></i></button></template><template v-else><button v-for="(e,i) in row.events" :key="e.id" class="entity-dot" :class="{alert:e.severity!=='normal'}" :style="{left:pos(e.t)+'%',top:8+sources.findIndex(s=>s.id===e.source)*7+'px',width:e.end?Math.max(.6,pos(e.end)-pos(e.t))+'%':'6px',background:sources.find(s=>s.id===e.source).color}" :title="e.title+' · '+clock(e.t)" @click="select(e.id)"></button></template></div><div class="entity-label"><strong dir="ltr">{{row.id}}</strong><small>{{row.events.length.toLocaleString()}} רשומות · {{new Set(row.events.map(e=>e.source)).size}} מערכות</small></div></div></div><div class="source-legend"><span v-for="s in sources" :key="s.id"><i :style="{background:s.color}"></i>{{s.label}}</span></div></template>